import 'dart:io';

const _fixtureDirectory = 'test/fixtures/workbench';
const _outputPath = 'test/fixtures/workbench/workbench_fixtures.g.dart';

void main() {
  final files = Directory(_fixtureDirectory)
      .listSync()
      .whereType<File>()
      .where((file) => file.path.endsWith('.json'))
      .toList()
    ..sort((left, right) => left.path.compareTo(right.path));
  final output = StringBuffer(
    '// GENERATED CODE - DO NOT MODIFY BY HAND\n'
    '// Generated by tool/gen_workbench_fixtures.dart.\n'
    'const workbenchFixtures = <String, String>{\n',
  );
  for (final file in files) {
    final name = file.uri.pathSegments.last;
    final contents = file.readAsStringSync();
    if (contents.contains("'''") || name.contains("'")) {
      throw StateError(
          'Fixture cannot be represented as a raw Dart string: $name');
    }
    output.writeln("  '$name': r'''$contents''',");
  }
  output.write('};\n');
  File(_outputPath).writeAsStringSync(output.toString());
  // Emit formatter-clean output so the format gate and the freshness check agree.
  final format = Process.runSync('dart', ['format', _outputPath]);
  if (format.exitCode != 0) {
    throw StateError('dart format failed on $_outputPath: ${format.stderr}');
  }
}
